    const p = getPayload(evt);
    return (
      p.session?.id ??
      p.sessionId ??
      p.sessionID ??
      p.session_id ??
      p.session ??
      null
    );
  }

  async function toast(
    message: string,
    variant: "info" | "success" | "error" = "info",
  ) {
    try {
      await client.tui.showToast({ body: { message, variant } });
    } catch {
